/*
 * A381800  a(n) = number of distinct residues r mod n of numbers k such that
 *          rad(k) | n, where rad = A007947.
 * https://oeis.org/A381800
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of distinct residues r (mod n) for which there
 *            exists k with rad(k) | n. The set of such residues is the
 *            multiplicative monoid generated by the prime residues dividing
 *            n. We compute its size by a breadth‑first search over the
 *            residue classes modulo n. Complexity is O(n · ω(n)), whic...
 * Range:     u8 n <= 537, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* multiply two unsigned 64‑bit integers modulo mod (no overflow). */
static inline idx_t mod_mul_u64(idx_t a, idx_t b, idx_t mod)
{
    return (idx_t)(((__int128)a * b) % mod);
}

/* integer square root of n (0 ≤ n ≤ 2^64–1). */
static inline idx_t isqrt_u64(idx_t n)
{
    idx_t lo = 0, hi = n;
    while (lo < hi) {
        idx_t mid = lo + (hi - lo) / 2;
        if ((__int128)mid * mid <= n)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo - 1;
}

/* factor n and store its distinct prime factors in primes[0..sz-1].
   Returns the number of distinct primes found.  primes is assumed
   to have space for at least 64 elements. */
static inline size_t factor_unique_primes(idx_t n, idx_t *primes, size_t sz)
{
    size_t cnt = 0;
    if (n <= 1) return 0;

    if (n % 2 == 0) {
        if (cnt < sz) primes[cnt++] = 2;
        while (n % 2 == 0) n /= 2;
    }
    idx_t limit = isqrt_u64(n);
    for (idx_t p = 3; p <= limit; p += 2) {
        if (n % p == 0) {
            if (cnt < sz) primes[cnt++] = p;
            while (n % p == 0) n /= p;
            limit = isqrt_u64(n);
        }
    }
    if (n > 1) {
        if (cnt < sz) primes[cnt++] = n;
    }
    return cnt;
}

seq_t a(idx_t n)
{
    if (n == 1) return (seq_t)1;

    /* distinct prime factors of n */
    idx_t prime_buf[64];
    size_t pcnt = factor_unique_primes(n, prime_buf, 64);

    /* visited residues */
    unsigned char *vis = (unsigned char *)calloc((size_t)n, sizeof(unsigned char));
    if (!vis) return (seq_t)0;     /* allocation failure */

    /* work queue for BFS */
    idx_t *queue = (idx_t *)malloc((size_t)n * sizeof(idx_t));
    if (!queue) { free(vis); return (seq_t)0; }

    size_t qhead = 0, qtail = 0;
    vis[1 % n] = 1;
    queue[qtail++] = 1 % n;

    while (qhead < qtail) {
        idx_t r = queue[qhead++];
        for (size_t i = 0; i < pcnt; ++i) {
            idx_t p = prime_buf[i];
            idx_t nr = mod_mul_u64(r, p, n);
            if (!vis[nr]) {
                vis[nr] = 1;
                queue[qtail++] = nr;
                if (qtail == n) {   /* all residues seen */
                    qtail = n;
                    break;
                }
            }
        }
    }

    seq_t cnt = 0;
    for (size_t i = 0; i < (size_t)n; ++i) {
        if (vis[i]) ++cnt;
    }

    free(vis);
    free(queue);
    return cnt;
}
